import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
# ── ALL ──
E('ALL','M2-N1','Servire il cliente allergico: la procedura di sala',[
 CL("È un allergene da dichiarare?","Seleziona un ingrediente, poi la colonna corretta.",["Allergene dell’Allegato II","Non è nell’elenco"],[
  ["Farina di frumento",0,"I cereali contenenti glutine sono nell’Allegato II."],["Sesamo",0,"Il sesamo è nell’Allegato II."],["Senape",0,"La senape è nell’Allegato II."],
  ["Pomodoro",1,"Il pomodoro non è tra le 14 sostanze dell’Allegato II."],["Lupini",0,"I lupini sono nell’Allegato II."],["Fragole",1,"Le fragole non sono nell’elenco, anche se possono dare reazioni."],
  ["Sedano",0,"Il sedano è nell’Allegato II."],["Vino con 50 mg/l di solfiti",0,"Anidride solforosa e solfiti oltre 10 mg/l, espressi come SO₂, sono nell’Allegato II."]],
  "Otto ingredienti. Riconosci quali sono allergeni da dichiarare secondo l’Allegato II del regolamento europeo millecentosessantanove del duemilaundici.","Reg. (UE) 1169/2011, Allegato II"),
 SC("Il cliente allergico alla frutta a guscio","Un cliente al ristorante dichiara un’allergia grave alla frutta a guscio e chiede se le trofie al pesto sono adatte. Il pesto è preparato in cucina.",[
  ("Che cosa risponde il cameriere?",[["«No, il pesto di solito non ha noci»",False,"Le informazioni devono basarsi sulla documentazione della ricetta, non su supposizioni."],["Verifica la scheda della ricetta o chiede al responsabile di cucina prima di rispondere",True,"Corretto: le informazioni sugli allergeni si danno sulla base della documentazione disponibile."],["Consiglia di scegliere un altro piatto senza verificare",False,"Il cliente ha diritto a informazioni corrette sul piatto richiesto."]]),
  ("La ricetta contiene pinoli e anacardi. Il cliente chiede una versione senza. Che cosa fa la cucina?",[["Prepara il pesto con gli stessi utensili, togliendo solo gli anacardi",False,"I pinoli non sono frutta a guscio nell’elenco, ma gli utensili contaminati possono trasferire l’allergene: servono utensili puliti e separati."],["Prepara una porzione dedicata con utensili e superfici puliti, evitando ogni contatto con la frutta a guscio",True,"Corretto: la prevenzione del contatto crociato è parte della procedura di sala e di cucina."],["Rifiuta qualsiasi richiesta",False,"Si può servire il cliente, se la procedura permette di evitare il contatto crociato in modo affidabile."]]),
  ("Il piatto esce dalla cucina. Che cosa serve per evitare errori?",[["Nulla: il cameriere ricorda la richiesta",False,"Serve un segnale chiaro lungo tutto il percorso del piatto."],["Un’identificazione chiara del piatto per il cliente allergico e la consegna diretta da parte di chi ha ricevuto la richiesta",True,"Corretto: identificazione e consegna dedicata riducono gli scambi di piatti."],["Servirlo insieme agli altri piatti del tavolo",False,"Aumenta il rischio di scambio o di contatto."]])],
  "Informazioni basate sulla documentazione, preparazione separata e consegna identificata: tre passaggi che proteggono il cliente allergico.","Un cliente con un’allergia grave chiede un piatto. Segui il percorso dalla sala alla cucina e ritorno.","Reg. (UE) 1169/2011 · D.lgs. 231/2017")])
# ── CER ──
E('CER','M1-N1','Indicatori: autoconsumo e autosufficienza',[
 ES("Esempio guidato · Autoconsumo e autosufficienza","Due indicatori che si confondono spesso.",[
  ["Dati dell’anno","Produzione dell’impianto 60.000 kWh; consumi dell’azienda 100.000 kWh; energia prodotta e consumata in sito 39.000 kWh.","P = 60.000 · C = 100.000 · Autoconsumata = 39.000 kWh"],
  ["Autoconsumo","Quota della produzione consumata in sito.","39.000 ÷ 60.000 = 65%"],
  ["Autosufficienza","Quota dei consumi coperta dall’impianto.","39.000 ÷ 100.000 = 39%"],
  ["Energia immessa in rete","Produzione non consumata in sito.","60.000 − 39.000 = 21.000 kWh"],
  ["Lettura","Un impianto più grande aumenta l’autosufficienza ma, senza accumulo o spostamento dei carichi, riduce l’autoconsumo.","Si dimensiona sui consumi contemporanei alla produzione"]],
  "Due indicatori che si confondono spesso. L’impianto produce sessantamila chilowattora; l’azienda ne consuma centomila; trentanovemila sono prodotti e consumati in sito. L’autoconsumo è la quota della produzione usata in sito: trentanovemila su sessantamila, il sessantacinque per cento. L’autosufficienza è la quota dei consumi coperta dall’impianto: trentanovemila su centomila, il trentanove per cento. Il resto della produzione, ventunomila chilowattora, va in rete. Ingrandire l’impianto aumenta l’autosufficienza, ma senza accumulo o spostamento dei carichi riduce l’autoconsumo.","CEI 0-21 · ARERA"),
 {"t":"grafico","tit":"Calcola autoconsumo e autosufficienza","lead":"Modifica produzione, consumi e quota consumata in sito.","rif":"Elaborazione didattica",
  "grafico":{"tipo":"calcolo","formula_testo":"Autoconsumo = E autoconsumata / Produzione · Autosufficienza = E autoconsumata / Consumi",
   "ingressi":[{"id":"p","nome":"Produzione annua","min":5000,"max":300000,"passo":5000,"val":60000,"unita":"kWh"},{"id":"c","nome":"Consumi annui","min":10000,"max":500000,"passo":5000,"val":100000,"unita":"kWh"},{"id":"q","nome":"Quota della produzione consumata in sito","min":10,"max":100,"passo":5,"val":65,"unita":"%"}],
   "risultati":[{"nome":"Autosufficienza","formula":"Math.min(100, p*q/c)","unita":"%"},{"nome":"Energia immessa in rete","formula":"p*(1-q/100)","unita":"kWh"}],"unita":"%","scala":100},
  "nar":"Prova a cambiare la dimensione dell’impianto e la quota consumata in sito. Osserva come varia l’autosufficienza e quanta energia finisce in rete."},
 SC("Il fotovoltaico dell’officina","Un’officina meccanica con 100.000 kWh di consumi annui, concentrati nei giorni feriali tra le 8 e le 17, valuta un impianto fotovoltaico sul tetto.",[
  ("Da dove parti?",[["Dall’impianto più grande che entra nel tetto",False,"Senza analizzare i consumi rischi di immettere in rete gran parte della produzione."],["Dall’analisi dei consumi orari e dagli interventi di efficienza",True,"Corretto: prima si riducono i consumi, poi si dimensiona l’impianto sui consumi contemporanei."],["Dall’accumulo, perché aumenta sempre la convenienza",False,"L’accumulo va valutato dopo aver dimensionato l’impianto sui consumi."]]),
  ("L’analisi mostra consumi bassi nel fine settimana. Che cosa ne deduci?",[["Nel fine settimana gran parte della produzione andrà in rete",True,"Corretto: è la produzione che non trova consumi contemporanei; si valorizza con il ritiro o con la condivisione."],["Il fine settimana non incide sul dimensionamento",False,"Incide sull’autoconsumo annuo."],["Conviene spegnere l’impianto nel fine settimana",False,"L’energia si può immettere e valorizzare."]]),
  ("Come valuti la convenienza?",[["Con il solo prezzo dei moduli",False,"Servono costi, energia autoconsumata, energia immessa e manutenzione nel tempo."],["Con un piano economico su tutta la vita utile: risparmi in bolletta, ricavi dell’energia immessa, costi di manutenzione",True,"Corretto: indicatori come tempo di ritorno e valore attuale netto richiedono tutti i flussi."],["Con la potenza installata",False,"La potenza da sola non dice nulla sulla convenienza."]])],
  "Prima i consumi e l’efficienza, poi la dimensione dell’impianto, infine il piano economico completo: è la sequenza che evita impianti sovradimensionati.","Un’officina valuta un impianto fotovoltaico. Prendi le decisioni nell’ordine giusto.","D.lgs. 199/2021")])
E('CER','M2-N1','Esercitazione · Configurazioni e caratteristiche',[
 CL("Quale configurazione?","Seleziona una situazione, poi la configurazione di autoconsumo diffuso.",["Gruppo di autoconsumatori che agiscono collettivamente","Autoconsumatore individuale a distanza","Comunità energetica rinnovabile"],[
  ["Condominio con impianto sul tetto che condivide l’energia tra gli appartamenti",0,"Gli autoconsumatori si trovano nello stesso edificio o condominio."],
  ["Impresa con impianto su un capannone e consumi in un altro sito dello stesso titolare",1,"Un unico cliente finale usa l’energia prodotta in un altro sito."],
  ["Cittadini, PMI e Comune che costituiscono un soggetto giuridico per condividere l’energia",2,"È una comunità energetica rinnovabile, soggetto giuridico autonomo."],
  ["Associazione di famiglie e parrocchia nella stessa cabina primaria",2,"Più soggetti diversi uniti in un soggetto giuridico: comunità energetica."],
  ["Palazzina di uffici con più clienti finali e un impianto comune",0,"Stesso edificio: gruppo di autoconsumatori."],
  ["Comune che usa l’energia di un suo impianto per alimentare un altro edificio comunale",1,"Stesso cliente finale, siti diversi: autoconsumo individuale a distanza."]],
  "Sei situazioni reali. Assegna ciascuna alla configurazione di autoconsumo diffuso corretta.","D.lgs. 199/2021 · TIAD (ARERA)"),
 VF("Energia condivisa e incentivi",[["L’energia condivisa si calcola ora per ora come minimo tra energia immessa e prelevata dai membri.",True,"Vero: è il criterio orario usato per gli incentivi."],["Per la tariffa premio, i punti di prelievo e gli impianti devono trovarsi sotto la stessa cabina primaria.",True,"Vero."],["Una comunità energetica può avere come scopo principale il profitto finanziario.",False,"Falso: lo scopo principale sono i benefici ambientali, economici e sociali per i membri e il territorio."]],"Tre affermazioni su energia condivisa e incentivi: vere o false?","D.lgs. 199/2021"),
 AP("La configurazione adatta a te","Valuta quale configurazione potrebbe interessare la tua organizzazione o il tuo territorio.",["Ho una copertura adatta a un impianto","Ho consumi in più siti dello stesso titolare","Sono in un condominio o in un edificio con più utenti","Il mio Comune promuove una comunità energetica","Ho consumi diurni elevati","Posso coinvolgere altre imprese della zona"],"Configurazione che valuteresti e motivo","Es.: autoconsumo a distanza tra capannone e magazzino, stessa cabina primaria",
  "Valuta la tua situazione: spunta le condizioni che ti riguardano e scrivi quale configurazione di autoconsumo valuteresti, spiegando perché.",2)])
# ── EMI ──
E('EMI','M1-N1','Esercitazione · Regimi e riferimenti',[
 CL("Quale regime autorizzativo?","Seleziona uno stabilimento, poi il regime più probabile.",["AIA","AUA (autorizzazione alle emissioni)","Attività in deroga o autorizzazione generale","Disciplina degli impianti termici civili"],[
  ["Grande impianto di produzione di cemento",0,"Le attività dell’Allegato VIII alla Parte II sono soggette ad AIA."],
  ["PMI con cabina di verniciatura e consumo di solventi oltre le soglie di deroga",1,"Le PMI non soggette ad AIA chiedono l’AUA, che comprende l’autorizzazione alle emissioni."],
  ["Laboratorio odontotecnico con emissioni scarsamente rilevanti",2,"Le attività dell’Allegato IV, parte I, alla Parte V sono in deroga."],
  ["Caldaia a metano per il riscaldamento degli uffici sotto le soglie del Titolo II",3,"Gli impianti termici civili seguono il Titolo II della Parte V."],
  ["Allevamento intensivo oltre le soglie dell’Allegato VIII",0,"Sopra le soglie è soggetto ad AIA."],
  ["Piccola officina che aderisce a un’autorizzazione di carattere generale regionale",2,"Le autorizzazioni generali dell’art. 272, comma 2, semplificano i casi tipici."]],
  "Sei stabilimenti. Indica il regime autorizzativo più probabile per le emissioni in atmosfera.","D.lgs. 152/2006, Parti II e V · D.P.R. 59/2013"),
 CL("Quale tecnologia di abbattimento?","Seleziona un’emissione, poi la tecnologia più adatta.",["Filtro a maniche","Carboni attivi","Combustione termica o catalitica","Scrubber a umido"],[
  ["Polveri da levigatura del legno",0,"Le polveri si trattengono efficacemente con filtri a maniche."],
  ["COV a bassa concentrazione da una piccola verniciatura",1,"Per basse concentrazioni di COV si usa l’adsorbimento su carboni attivi."],
  ["COV ad alta concentrazione da un forno di essiccazione",2,"Ad alte concentrazioni la combustione è più efficace e può recuperare calore."],
  ["Vapori acidi da un bagno di decapaggio",3,"I gas acidi solubili si abbattono per assorbimento a umido."],
  ["Polveri metalliche da una molatura",0,"Polveri: filtrazione a maniche o a cartucce."],
  ["Solventi da una linea di stampa con flussi elevati e continui",2,"Flussi elevati con COV in concentrazione utile: combustione termica rigenerativa."]],
  "Sei emissioni diverse. Associa a ciascuna la tecnologia di abbattimento più adatta.","D.lgs. 152/2006, Parte V · BAT")])
E('EMI','M1-N2','Caso di studio · Il filtro a maniche del venerdì sera',[
 SC("Il superamento e il guasto","Lunedì mattina il rapporto di prova dell’autocontrollo sul camino E3 indica polveri a 18 mg/Nm³, con limite autorizzato di 10 mg/Nm³. In reparto si scopre che alcune maniche del filtro sono rotte.",[
  ("Qual è la prima azione?",[["Attendere il prossimo autocontrollo per conferma",False,"Un guasto che non permette il rispetto dei limiti richiede azioni immediate."],["Comunicare il guasto all’autorità competente entro le otto ore e mettere in sicurezza l’impianto",True,"Corretto: in caso di guasti che non permettono il rispetto dei valori limite il gestore informa l’autorità entro le otto ore successive (art. 271, comma 14)."],["Sostituire le maniche senza comunicare nulla",False,"La comunicazione all’autorità è obbligatoria."]]),
  ("Come gestisci la produzione nel frattempo?",[["La riduci o la sospendi secondo le indicazioni dell’autorizzazione e dell’autorità, fino al ripristino",True,"Corretto: l’autorità può disporre riduzione o cessazione; il gestore agisce per riportare l’impianto alla conformità."],["Prosegui normalmente",False,"Con il filtro guasto le emissioni restano oltre il limite."],["Bypassi il filtro",False,"Il bypass peggiora le emissioni ed è vietato salvo casi autorizzati."]]),
  ("Che cosa resta da fare dopo la riparazione?",[["Archiviare il rapporto di prova",False,"Serve dimostrare il ritorno alla conformità."],["Ripetere la misura, registrare guasto e intervento e rivedere il piano di manutenzione",True,"Corretto: la nuova misura dimostra la conformità; la registrazione e la manutenzione evitano il ripetersi."],["Aumentare l’altezza del camino",False,"Non riduce le emissioni alla fonte."]])],
  "Comunicare entro otto ore, ridurre o fermare, riparare, misurare di nuovo e registrare: è la sequenza che protegge l’ambiente e l’impresa.","Un superamento scoperto con l’autocontrollo e un filtro guasto. Decidi la sequenza delle azioni.","D.lgs. 152/2006, art. 271, comma 14"),
 VF("Autocontrolli e comunicazioni",[["Un guasto che impedisce il rispetto dei limiti va comunicato all’autorità competente entro otto ore.",True,"Vero: art. 271, comma 14."],["Il rapporto di prova di un autocontrollo può essere conservato senza annotarne le non conformità.",False,"Falso: le non conformità vanno gestite e documentate secondo l’autorizzazione."],["La correzione all’ossigeno di riferimento si applica quando l’autorizzazione la prevede.",True,"Vero."]],"Tre affermazioni su autocontrolli e comunicazioni.","D.lgs. 152/2006, Parte V")])
E('EMI','M1-N3','Caso di studio · La prescrizione dopo il sopralluogo',[
 SC("L’ispezione dell’ARPA","Un tecnico dell’ARPA si presenta senza preavviso per un sopralluogo sulle emissioni dello stabilimento.",[
  ("Che cosa prepari per primo?",[["L’autorizzazione con il quadro emissivo, i rapporti di prova e il registro di manutenzione degli impianti di abbattimento",True,"Corretto: sono i documenti che il controllo verifica per primi."],["Solo il certificato camerale",False,"Servono i documenti specifici delle emissioni."],["Nulla: si risponde a voce",False,"Le evidenze documentali sono essenziali."]]),
  ("Il tecnico chiede di vedere il punto di prelievo del camino E2, non accessibile in sicurezza. Che cosa fai?",[["Lo accompagni con una scala a pioli improvvisata",False,"La sicurezza delle operazioni di campionamento è un requisito: non si improvvisa."],["Spieghi la situazione e la registri; il punto di prelievo va reso accessibile in sicurezza come previsto",True,"Corretto: accessibilità e sicurezza della postazione di prelievo sono parte dei requisiti."],["Dici che il camino non è più in uso",False,"Dichiarazioni non veritiere aggravano la posizione."]]),
  ("Al termine riceve una prescrizione con un termine per adeguarsi. Che cosa fai?",[["Rispetti il termine, documenti l’adeguamento e lo comunichi",True,"Corretto: l’adempimento nei termini consente di estinguere le contravvenzioni secondo la procedura prevista."],["Aspetti il prossimo controllo",False,"Il termine va rispettato."],["Contesti la prescrizione senza adeguarti",False,"Puoi presentare osservazioni, ma l’adeguamento resta dovuto."]])],
  "Documenti in ordine, postazioni di prelievo sicure e adeguamento nei termini: così un’ispezione si chiude senza conseguenze gravi.","Un’ispezione senza preavviso. Gestiscila passo dopo passo.","D.lgs. 152/2006, Parte V e Parte VI-bis"),
 AP("Le sorgenti del tuo stabilimento","Prepara il censimento delle emissioni della tua organizzazione.",["Cabine di verniciatura","Forni o essiccatoi","Generatori di calore","Lavorazioni con polveri","Uso di solventi","Saldatura","Impianti di abbattimento","Emissioni diffuse o odorigene"],"Camini e impianti di abbattimento presenti, con la relativa scadenza degli autocontrolli","Es.: E1 cabina di verniciatura, carboni attivi, autocontrollo annuale a marzo",
  "Prepara il censimento delle sorgenti di emissione del tuo stabilimento: indica le attività presenti e scrivi camini, impianti di abbattimento e scadenze degli autocontrolli.",3)])
